    n = draw(st.integers(1, 9))
    choice = draw(st.integers(0, 3))
    if choice == 0:
        # all equal elements
        v = draw(st.integers(1, 3))
        a = [v] * n
    elif choice == 1:
        # arithmetic-friendly small values with duplicates
        a = draw(st.lists(st.integers(1, 4), min_size=n, max_size=n))
    elif choice == 2:
        # sorted increasing with a common step
        start = draw(st.integers(1, 3))
        step = draw(st.integers(0, 3))
        a = [start + step * i for i in range(n)]
    else:
        # reverse sorted small values
        a = sorted(draw(st.lists(st.integers(1, 6), min_size=n, max_size=n)), reverse=True)
    return f"{n}\n{' '.join(map(str, a))}\n"

